// TH15 v1.00b Stage 4 Boss3 nonspell (5th attack in the normal interrupt chain).
// Source: st04bs.ecl.txt:995-1053 (entry), dependencies 331-469 / 1055-1133.
//
// Source shape: Boss3 waits 140 frames, then alternates Boss3_at / Boss3_at2 every
// 160 frames. Each call spawns 12 (Easy: 6) circle enemies every 5 (Easy: 10)
// frames; every 4th (starting with the first) is BCir03b (hp 400, color 6), the
// rest BCir03 (hp 200, color 2). Each child spirals out to r=100 over 120 frames
// (3 deg/frame), keeps orbiting, then leaves along FINAL_ANGLE at 3 px/frame.
// While alive it fires one talisman every 2 frames from frame 11 at
// FINAL_ANGLE + B, B advancing 3 deg (Boss3_at) or 2 deg (Boss3_at2) per shot.
//
// Approved synthesis choices for this card:
// - children are invulnerable and survive; BCir03Dead ($BI3 += 330) and the
//   boss flagExtDmg(1) damage feedback are not simulated, so child kills can
//   never advance the segment.
// - entry etClear/etCancel, enmKillAll, killAllAsync, drops, sounds, charge FX
//   and all ANM/scale/alpha/color/layer work are omitted (approved policy).
// - ANIM EX type2 a=1 spawn animation is omitted but its source retreat
//   (position -= 4 * velocity) is kept.
// - the 4-frame pre-timerReset entry cleanup is omitted; card frame 0 is the
//   source timerReset point (task: window 2400, TIME_LIMIT 120+2400+4).

const TIME_LIMIT: int = 2524;
const OPENING_BUFFER: int = 120;

// TH15 synthetic bullet aliases (type 11 == etSprite(0, 11, color)).
const TH15_TALISMAN: int = 528;

// globals free-segment flag: 1 while the Boss3 phase is running.
const G_PHASE_ACTIVE: int = 16;

// ---- shell -------------------------------------------------------------

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 18000, 0, 0, 0, boss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_global(G_PHASE_ACTIVE, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    set_global(G_PHASE_ACTIVE, 0);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

// ---- boss (st04bs.ecl.txt:995-1053 / 1055-1133) ------------------------

async sub boss_main() {
    set_invuln(65535);
    set_hurtbox(20fx);   // Boss init setHurtbox(40,40): radius 40*0.5
    set_hitbox(24fx);    // setHitbox(48,48): radius 48*0.5
    wait(140);           // source wait(140) after setInterrupt/lifeMarker
    while global(G_PHASE_ACTIVE) == 1 {
        boss_at();
        if global(G_PHASE_ACTIVE) == 0 { break; }
        boss_wait(20);
        boss_move_rand();
        boss_wait(80);
        boss_at2();
        if global(G_PHASE_ACTIVE) == 0 { break; }
        boss_wait(20);
        boss_move_rand();
        boss_wait(80);
    }
    // source sub ends via the slot-0 interrupt (BossCard3); segment handoff omitted.
}

// Boss3_at: %F0 starts at 0 and decreases 15 deg per child (Easy: 30 deg).
sub boss_at() {
    var count: int = 12;
    var gap: int = 5;
    var phase: angle = 0deg;
    var step: angle = 15deg;
    var speed: fx = 2fx;
    if global(GVAR_RANK) == RANK_EASY { count = 6; gap = 10; step = 30deg; }
    if global(GVAR_RANK) == RANK_HARD { speed = 2.5fx; }
    if global(GVAR_RANK) == RANK_LUNATIC { speed = 3fx; }
    var idx: int = -1;
    var i0: int = 60;
    for i in 0..count {
        if global(G_PHASE_ACTIVE) == 0 { break; }
        idx = idx + 1;
        var hp: int = 200;
        var color: int = 2;
        if idx % 4 == 0 { hp = 400; color = 6; }   // BCir03b every 4th
        _ = spawn_enemy($self_x, $self_y, hp, 0, 1000, 0,
                        cir_enemy(phase, i0, 3deg, color, speed));
        i0 = i0 - 5;
        phase = phase - step;
        boss_wait(gap);
    }
}

// Boss3_at2: %F0 starts at 0 and increases 15 deg per child (Easy: 30 deg),
// %F3 = 2 deg per shot instead of 3.
sub boss_at2() {
    var count: int = 12;
    var gap: int = 5;
    var phase: angle = 0deg;
    var step: angle = 15deg;
    var speed: fx = 2fx;
    if global(GVAR_RANK) == RANK_EASY { count = 6; gap = 10; step = 30deg; }
    if global(GVAR_RANK) == RANK_HARD { speed = 2.5fx; }
    if global(GVAR_RANK) == RANK_LUNATIC { speed = 3fx; }
    var idx: int = -1;
    var i0: int = 60;
    for i in 0..count {
        if global(G_PHASE_ACTIVE) == 0 { break; }
        idx = idx + 1;
        var hp: int = 200;
        var color: int = 2;
        if idx % 4 == 0 { hp = 400; color = 6; }
        _ = spawn_enemy($self_x, $self_y, hp, 0, 1000, 0,
                        cir_enemy(phase, i0, 2deg, color, speed));
        i0 = i0 - 5;
        phase = phase + step;
        boss_wait(gap);
    }
}

// moveRand(60, 4, 1.0) sample from the shared TH16 recipe, adapted to
// moveLimit(0, 128, 280, 64): per-frame clamp x in [-140,140], y in [96,160],
// direction inner region x in [-70,70], y in [112,144].
sub boss_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }   // source normalizes this branch only
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
        // deliberately not normalized before the source fabs tests
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // native +/-pi/2 guard, epsilon 0.05 rad; nearest BAM boundaries
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    boss_begin_angle(a as angle);
}

sub boss_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    boss_arm_next_step();
}

sub boss_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub boss_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        boss_arm_next_step();
    }
}

// ---- circle enemy (st04bs.ecl.txt:331-469) -----------------------------

// BCir03/BCir03b: moveCircle(%F0, 0.05236, 0, 0) then
// moveCircleTime(120, linear, -, 100, -); orbit continues after the growth;
// after wait(120)+wait($I0) the child leaves along FINAL_ANGLE at 3 px/frame.
// The emitter task (BCir03_at) waits 10 of its own frames, then fires
// etCount(1,1)/mode3 single bullets every 2 frames, 400 times or until
// killAsync(1) at departure. Both are folded into one per-frame task here.
async sub cir_enemy(theta0: angle, i0: int, ang_step: angle, color: int, speed: fx) {
    set_invuln(65535);
    set_hurtbox(12fx);   // setHurtbox(24,24): radius 12
    set_hitbox(8fx);     // setHitbox(16,16): radius 8
    var cx: fx = $self_x;          // circle center snapshot at moveCircle
    var cy: fx = $self_y;
    var theta: angle = theta0;
    var last_x: fx = $self_x;      // P(f-1)
    var last_y: fx = $self_y;
    var b: angle = 0deg;           // %B
    var dir: angle = 0deg;         // %FINAL_ANGLE of the current frame
    var f: int = 0;
    var depart: int = 120 + i0;    // wait(120) + wait($I0)
    while f < depart && global(G_PHASE_ACTIVE) == 1 {
        if f >= 1 {
            dir = atan2($self_y - last_y, $self_x - last_x);
        }
        if f >= 11 && f % 2 == 1 {
            // etAngle(FINAL_ANGLE + B); etOn; EX ANIM a=1 retreat 4*velocity.
            var a: angle = dir + b;
            var back: fx = 4fx * speed;
            _ = fire(TH15_TALISMAN, color,
                     $self_x - back * cos(a), $self_y - back * sin(a),
                     speed, a, none, none);
            b = b + ang_step;
        }
        last_x = $self_x;
        last_y = $self_y;
        // next spiral point P(f+1): r rises 0->100 over the first 120 ticks.
        theta = theta + 3deg;
        var k: int = f + 1;
        var r: fx = 100fx;
        if k <= 120 { r = (k * 5) as fx / 6fx; }
        var nx: fx = cx + r * cos(theta);
        var ny: fx = cy + r * sin(theta);
        move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
        f = f + 1;
        wait(1);
    }
    if global(G_PHASE_ACTIVE) == 0 { return; }
    dir = atan2($self_y - last_y, $self_x - last_x);
    move_vel(0, dir, 3fx, EASE_LINEAR);   // moveVel(%FINAL_ANGLE, 3.0) + killAsync(1)
    loop { wait(1000); }
}
